/**
 * Everything the site says about the WDS Scenario Picker's current release,
 * read from the one file a release edits: public/picker/latest.json.
 *
 * That same file is what every shipped Picker build reads at start-up
 * (https://warbox.org/picker/latest.json, baked into the exe), so the
 * version on the site's Download buttons can never disagree with the in-app
 * update notice. The Picker reads only `version`, `released` and
 * `download_url`; `zip_url` and `zip_bytes` are for this site.
 *
 * The supported-games list is generated by the WDS repo's
 * tools/warbox_site/sync_picker_games.py — never edit it by hand.
 */
import latest from '../../public/picker/latest.json';
import gamesFile from '../data/picker-games.json';

interface LatestJson {
  version: string;
  released: string;
  download_url: string;
  zip_url?: string;
  zip_bytes?: number;
}

const feed = latest as LatestJson;

/** KB below a megabyte, otherwise one decimal of MB. */
function formatSize(bytes: number): string {
  return bytes < 1024 * 1024
    ? `${Math.max(1, Math.round(bytes / 1024))} KB`
    : `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

export const PICKER = {
  name: 'WDS Scenario Picker',
  version: feed.version,
  released: new Date(`${feed.released}T00:00:00Z`),
  /**
   * The zip itself when latest.json names one; otherwise the release's
   * download_url (before the GitHub Releases move that was a bit.ly link).
   * Never the product page — that would send the button back to itself.
   */
  downloadHref:
    feed.zip_url ?? (feed.download_url.startsWith('https://warbox.org/picker') ? undefined : feed.download_url),
  size: typeof feed.zip_bytes === 'number' ? formatSize(feed.zip_bytes) : undefined,
  platform: 'Windows 10/11, 64-bit',
  /** Baked into future Picker builds' "Send feedback" link. Never change it. */
  feedbackHref: '/contact/?about=picker',
} as const;

export interface PickerGame {
  id: string;
  series: string;
  title: string;
  is_demo: boolean;
  is_mod: boolean;
  base_game?: string;
  cover: string | null;
}

const covers = import.meta.glob<{ default: ImageMetadata }>('../assets/picker/covers/*.{png,gif,jpg,jpeg}', {
  eager: true,
});

export function coverOf(game: PickerGame): ImageMetadata | undefined {
  return game.cover ? covers[`../assets/picker/covers/${game.cover}`]?.default : undefined;
}

export const PICKER_GAMES: PickerGame[] = (gamesFile as { games: PickerGame[] }).games;

/** Games grouped by series, the biggest series first, then alphabetically. */
export function pickerGamesBySeries(): { series: string; games: PickerGame[] }[] {
  const groups = new Map<string, PickerGame[]>();
  for (const game of PICKER_GAMES) {
    groups.set(game.series, [...(groups.get(game.series) ?? []), game]);
  }
  return [...groups.entries()]
    .map(([series, games]) => ({ series, games }))
    .sort((a, b) => b.games.length - a.games.length || a.series.localeCompare(b.series));
}

/**
 * Screenshots: drop a file named after one of these slots into
 * src/assets/picker/screenshots/ (any of png/jpg/webp) and it replaces the
 * placeholder. No code change.
 */
export const SCREENSHOT_SLOTS = [
  { file: 'scenario-table', caption: 'The scenario table — sortable, filterable, colour-coded' },
  { file: 'scenario-info', caption: 'Scenario Info — the full description and designer notes' },
  { file: 'all-scenarios', caption: 'All Scenarios — every installed game in one list' },
  { file: 'saved-games', caption: 'Saved Games — every save and PBEM turn file in one place' },
  { file: 'play-log', caption: 'My Play Log — your results and notes per scenario' },
  { file: 'blitz-balance', caption: 'Blitz Balance — TheBlitz.club ratings and win balance' },
] as const;

const shots = import.meta.glob<{ default: ImageMetadata }>('../assets/picker/screenshots/*.{png,jpg,jpeg,webp}', {
  eager: true,
});

export function screenshotOf(file: string): ImageMetadata | undefined {
  const hit = Object.entries(shots).find(([path]) => path.split('/').pop()?.replace(/\.[^.]+$/, '') === file);
  return hit?.[1].default;
}
